import{_ as e,c as l,o as r,ag as o}from"./chunks/framework.B1jFR3yW.js";const _=JSON.parse('{"title":"js性能优化","description":"","frontmatter":{},"headers":[],"relativePath":"随记/代码库/009-js性能优化.md","filePath":"随记/代码库/009-js性能优化.md"}'),i={name:"随记/代码库/009-js性能优化.md"};function t(s,a,n,d,h,c){return r(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="js性能优化" tabindex="-1">js性能优化 <a class="header-anchor" href="#js性能优化" aria-label="Permalink to &quot;js性能优化&quot;">​</a></h1><h2 id="一、图片优化" tabindex="-1">一、图片优化 <a class="header-anchor" href="#一、图片优化" aria-label="Permalink to &quot;一、图片优化&quot;">​</a></h2><ol><li>不用图片，使用字体图标来代替，使用css代替</li><li>小图片使用base64</li><li>雪碧图</li><li>使用正确的图片格式，对于能够显示webg格式的浏览器，尽量使用webg格式。</li></ol><h2 id="二、使用cdn" tabindex="-1">二、使用CDN <a class="header-anchor" href="#二、使用cdn" aria-label="Permalink to &quot;二、使用CDN&quot;">​</a></h2><p>CDN的优点：</p><ol><li>分发服务器：主要作用是缓存，负责响应用户的请求，将缓存的内容直接提供给用户。</li><li>负载均衡服务：动态决定新请求访问进哪一台（压力小的那台）。</li><li>地理位置：他在很多地方都有服务器，会影响地理位置离请求较近的服务响应。</li></ol><h2 id="三、懒加载" tabindex="-1">三、懒加载 <a class="header-anchor" href="#三、懒加载" aria-label="Permalink to &quot;三、懒加载&quot;">​</a></h2><ol><li><p>按需加载，比如动态路由或者图片资源代理，大资源我就有一个小图标代替，但我不加载，需要使用的时候才加载。</p></li><li><p>延迟不需要的首屏加载，使用async和defer属性等方法。</p></li></ol><h2 id="四、减少dom操作" tabindex="-1">四、减少DOM操作 <a class="header-anchor" href="#四、减少dom操作" aria-label="Permalink to &quot;四、减少DOM操作&quot;">​</a></h2><ol><li>减少dom访问，比如事件绑定，尽量使用事件委托。</li><li>documentFragement</li><li>使用requestAnimationFrame来替代setTimeout和setInterval</li></ol><h2 id="五、减少服务器请求" tabindex="-1">五、减少服务器请求 <a class="header-anchor" href="#五、减少服务器请求" aria-label="Permalink to &quot;五、减少服务器请求&quot;">​</a></h2><ol><li>防抖节流</li></ol><h2 id="六、使用-web-workers-处理需要大量执行时间的代码" tabindex="-1">六、使用 web workers 处理需要大量执行时间的代码 <a class="header-anchor" href="#六、使用-web-workers-处理需要大量执行时间的代码" aria-label="Permalink to &quot;六、使用 web workers 处理需要大量执行时间的代码&quot;">​</a></h2><h3 id="web-workers-的几个使用场景" tabindex="-1">web workers 的几个使用场景 <a class="header-anchor" href="#web-workers-的几个使用场景" aria-label="Permalink to &quot;web workers 的几个使用场景&quot;">​</a></h3><ol><li>预取数据 — 优化网站的加载时间，可用 web workers 来提前加载数据。</li><li>轮询工作</li></ol>',15)])])}const m=e(i,[["render",t]]);export{_ as __pageData,m as default};
